function criarElemento(tag, texto, classe) { const elemento = document.createElement(tag); elemento.textContent = texto; if (classe) elemento.className = classe; return elemento; } function criarPagina(titulo, descricao, idTitulo) { const secao = document.createElement("section"); const tituloPagina = criarElemento("h1", titulo); tituloPagina.id = idTitulo; secao.setAttribute("aria-labelledby", idTitulo); secao.append(tituloPagina, criarElemento("p", descricao)); return secao; } function criarCampo(id, rotulo, tipo, autocomplete) { const grupo = document.createElement("p"); grupo.className = "campo-formulario"; const label = criarElemento("label", rotulo); const input = document.createElement("input"); label.htmlFor = id; input.id = id; input.name = id; input.type = tipo; input.required = true; input.autocomplete = autocomplete; const erro = document.createElement("span"); erro.id = `erro-${id}`; erro.className = "mensagem-erro"; erro.setAttribute("aria-live", "polite"); input.setAttribute("aria-describedby", erro.id); grupo.append(label, input, erro); return grupo; } function criarToast() { const toast = document.createElement("div"); const conteudo = document.createElement("div"); const texto = criarElemento("div", "Cadastro salvo com sucesso.", "toast-body"); const fechar = document.createElement("button"); toast.id = "toast-cadastro"; toast.className = "toast align-items-center text-bg-success border-0 position-fixed bottom-0 end-0 m-3"; toast.setAttribute("role", "status"); toast.setAttribute("aria-live", "polite"); toast.setAttribute("aria-atomic", "true"); conteudo.className = "d-flex"; fechar.type = "button"; fechar.className = "btn-close btn-close-white me-2 m-auto"; fechar.setAttribute("data-bs-dismiss", "toast"); fechar.setAttribute("aria-label", "Fechar aviso"); conteudo.append(texto, fechar); toast.append(conteudo); return toast; } function templateInicio() { const secao = criarPagina( "EducaÃ§Ã£o antirracista transforma vidas", "ConheÃ§a o Instituto RaÃ­zes da Igualdade e participe da construÃ§Ã£o de uma educaÃ§Ã£o mais justa.", "titulo-inicio" ); const imagem = document.createElement("img"); const fonteWebp = document.createElement("source"); const figura = document.createElement("figure"); const picture = document.createElement("picture"); fonteWebp.srcset = "imagens/educacao-antirracista-480.webp 480w, imagens/educacao-antirracista-960.webp 960w"; fonteWebp.sizes = "(max-width: 600px) 100vw, 960px"; fonteWebp.type = "image/webp"; imagem.src = "imagens/educacao-antirracista-960.jpg"; imagem.alt = "Estudantes negros e uma educadora reunidos em uma atividade de leitura."; imagem.width = 960; imagem.height = 540; imagem.loading = "lazy"; imagem.decoding = "async"; picture.append(fonteWebp, imagem); figura.className = "imagem-destaque"; figura.append(picture); secao.append(figura); return secao; } function templateProjetos() { const secao = criarPagina( "Projetos em destaque", "Nossas iniciativas levam formaÃ§Ã£o, literatura e cidadania para escolas e comunidades.", "titulo-projetos" ); const lista = document.createElement("div"); lista.className = "lista-projetos"; const modeloProjeto = document.querySelector("#template-projeto"); const projetos = [ { titulo: "BaobÃ¡ nas Escolas", descricao: "FormaÃ§Ã£o continuada de educadores para uma prÃ¡tica pedagÃ³gica antirracista." }, { titulo: "Quilombo LiterÃ¡rio", descricao: "DistribuiÃ§Ã£o de literatura com protagonistas negros e indÃ­genas." }, { titulo: "Projeto VOZES", descricao: "Oficinas de audiovisual e cidadania para jovens das periferias." } ]; projetos.forEach((projeto) => { const card = modeloProjeto.content.cloneNode(true); card.querySelector("[data-titulo]").textContent = projeto.titulo; card.querySelector("[data-descricao]").textContent = projeto.descricao; lista.append(card); }); secao.append(lista); return secao; } function templateCadastro() { const secao = criarPagina( "FaÃ§a parte da transformaÃ§Ã£o", "Preencha seus dados para demonstrar interesse em voluntariado, doaÃ§Ã£o ou parceria.", "titulo-cadastro" ); const formulario = document.createElement("form"); const mensagem = document.createElement("p"); const botao = criarElemento("button", "Enviar interesse"); formulario.id = "formulario-cadastro"; formulario.noValidate = true; formulario.append( criarCampo("nome", "Nome completo", "text", "name"), criarCampo("email", "E-mail", "email", "email") ); mensagem.id = "feedback-cadastro"; mensagem.className = "feedback-formulario"; mensagem.setAttribute("role", "status"); mensagem.setAttribute("aria-live", "polite"); botao.type = "submit"; formulario.append(mensagem, botao); secao.append(formulario, criarToast()); return secao; } window.templates = { templateCadastro, templateInicio, templateProjetos };